@Composable
fun Gate(allow: Boolean = false, modifier: Modifier = Modifier, content: @Composable (Modifier) -> Unit) {
  var ready by remember { mutableStateOf(false) }
  if (!ready) {
    Button({
      Text("Loading")
    }, onPress = { 
    ready = true
}, header = false, modifier = modifier)
  } else if (!allow) {
    Text("Unavailable", header = false, modifier = modifier)
  } else {
    content(modifier)
  }
}

@Composable
fun Feeds(names: List<String>, modifier: Modifier = Modifier) {
  Gate(names.count < 3L, modifier = modifier) { contentModifier ->
    VStack(title = "Feeds", modifier = contentModifier) {
      for (name in names) {
        Card() { contentModifier ->
          Text(name, modifier = contentModifier)
        }
      }
    }
  }
}

